/**
 * Core TypeScript types and interfaces for the blog demo.
 */

/** A unique identifier string used for posts, comments, and related entities. */
export type ID = string;

/** ISO-8601 date string representation. */
export type ISODateString = string;

/** Basic author information shared by posts and comments. */
export interface Author {
  id: ID;
  name: string;
  avatarUrl?: string;
}

/** A blog post in the demo. */
export interface BlogPost {
  id: ID;
  title: string;
  slug: string;
  excerpt: string;
  content: string;
  author: Author;
  tags: string[];
  createdAt: ISODateString;
  updatedAt: ISODateString;
  published: boolean;
}

/** A comment attached to a blog post. */
export interface Comment {
  id: ID;
  postId: ID;
  author: Author;
  content: string;
  createdAt: ISODateString;
  updatedAt: ISODateString;
  parentCommentId?: ID;
}

/** High-level state for the blog demo UI/data store. */
export interface DemoState {
  posts: BlogPost[];
  comments: Comment[];
  selectedPostId?: ID;
  loading: boolean;
  error?: string;
}

/** Input data for creating a new blog post. */
export interface CreatePostInput {
  title: string;
  slug: string;
  excerpt: string;
  content: string;
  author: Author;
  tags?: string[];
  published?: boolean;
}

/** Input data for updating an existing blog post. */
export interface UpdatePostInput {
  title?: string;
  slug?: string;
  excerpt?: string;
  content?: string;
  tags?: string[];
  published?: boolean;
}

/** Input data for creating a new comment. */
export interface CreateCommentInput {
  postId: ID;
  author: Author;
  content: string;
  parentCommentId?: ID;
}

/** Generic success result wrapper. */
export interface SuccessResult<T> {
  ok: true;
  data: T;
}

/** Generic error result wrapper. */
export interface ErrorResult {
  ok: false;
  error: string;
}

/** Result shape returned by helper functions that may fail. */
export type Result<T> = SuccessResult<T> | ErrorResult;

/** Pagination information for list-style helpers. */
export interface Pagination {
  page: number;
  pageSize: number;
  totalItems: number;
  totalPages: number;
}

/** Result shape for paginated list helpers. */
export interface PaginatedResult<T> {
  items: T[];
  pagination: Pagination;
}

/** Sorting direction used by list helpers. */
export type SortDirection = 'asc' | 'desc';

/** Generic sort descriptor for list helpers. */
export interface SortDescriptor<TField extends string = string> {
  field: TField;
  direction: SortDirection;
}

/** Filter options for querying posts in the demo. */
export interface PostFilter {
  authorId?: ID;
  tag?: string;
  published?: boolean;
  search?: string;
}

/** Filter options for querying comments in the demo. */
export interface CommentFilter {
  postId?: ID;
  authorId?: ID;
  parentCommentId?: ID | null;
  search?: string;
}

/** Lightweight identifier/title pair for menus and selectors. */
export interface OptionItem {
  id: ID;
  label: string;
}

/** Shared metadata attached to demo entities or helper outputs. */
export interface Metadata {
  createdAt: ISODateString;
  updatedAt: ISODateString;
}

/**
 * In-memory blog demo with seeded data and simple pure operations.
 */

export interface Comment {
  id: number;
  author: string;
  body: string;
  createdAt: string;
}

export interface Post {
  id: number;
  slug: string;
  title: string;
  excerpt: string;
  body: string;
  tags: string[];
  createdAt: string;
  updatedAt: string;
  comments: Comment[];
}

export interface BlogState {
  posts: Post[];
  nextPostId: number;
  nextCommentId: number;
}

export interface CreatePostInput {
  title: string;
  excerpt?: string;
  body: string;
  tags?: string[];
}

export interface AddCommentInput {
  postId?: number;
  slug?: string;
  author: string;
  body: string;
}

export interface SearchResult {
  post: Post;
  score: number;
}

/**
 * Creates the initial blog state with seeded posts and comments.
 */
export function createSeededBlogState(): BlogState {
  const now = new Date().toISOString();

  const posts: Post[] = [
    {
      id: 1,
      slug: 'hello-typescript',
      title: 'Hello TypeScript',
      excerpt: 'A tiny post introducing the demo.',
      body: 'TypeScript helps build safer JavaScript applications with static types.',
      tags: ['typescript', 'demo', 'intro'],
      createdAt: now,
      updatedAt: now,
      comments: [
        {
          id: 1,
          author: 'Ada',
          body: 'Great intro!',
          createdAt: now,
        },
      ],
    },
    {
      id: 2,
      slug: 'in-memory-patterns',
      title: 'In-Memory Patterns',
      excerpt: 'Store blog data in plain objects and arrays.',
      body: 'In-memory demos are great for exploring CRUD behavior without a database.',
      tags: ['patterns', 'memory', 'crud'],
      createdAt: now,
      updatedAt: now,
      comments: [],
    },
    {
      id: 3,
      slug: 'searching-posts',
      title: 'Searching Posts',
      excerpt: 'Look up blog posts by text and tags.',
      body: 'Searching can match title, excerpt, body, and tags in a simple demo.',
      tags: ['search', 'demo'],
      createdAt: now,
      updatedAt: now,
      comments: [
        {
          id: 2,
          author: 'Lin',
          body: 'Useful for tiny prototypes.',
          createdAt: now,
        },
      ],
    },
  ];

  return {
    posts,
    nextPostId: 4,
    nextCommentId: 3,
  };
}

/**
 * Returns a copy of all posts in the given state.
 */
export function listPosts(state: BlogState): Post[] {
  return state.posts.map(clonePost);
}

/**
 * Reads a post by numeric id or slug.
 */
export function readPost(state: BlogState, idOrSlug: number | string): Post | undefined {
  const post = typeof idOrSlug === 'number'
    ? state.posts.find((candidate: Post) => candidate.id === idOrSlug)
    : state.posts.find((candidate: Post) => candidate.slug === idOrSlug);

  return post ? clonePost(post) : undefined;
}

/**
 * Creates a new post and returns the new state plus created post.
 */
export function createPost(state: BlogState, input: CreatePostInput): { state: BlogState; post: Post } {
  const now = new Date().toISOString();
  const slug = uniqueSlug(state.posts, slugify(input.title));
  const excerpt = input.excerpt?.trim() || buildExcerpt(input.body);
  const post: Post = {
    id: state.nextPostId,
    slug,
    title: input.title.trim(),
    excerpt,
    body: input.body,
    tags: normalizeTags(input.tags),
    createdAt: now,
    updatedAt: now,
    comments: [],
  };

  return {
    state: {
      posts: [...state.posts, post],
      nextPostId: state.nextPostId + 1,
      nextCommentId: state.nextCommentId,
    },
    post: clonePost(post),
  };
}

/**
 * Adds a comment to a post identified by id or slug and returns the new state plus updated post.
 */
export function addComment(
  state: BlogState,
  input: AddCommentInput,
): { state: BlogState; post: Post } | undefined {
  const index = findPostIndex(state.posts, input.postId, input.slug);
  if (index < 0) {
    return undefined;
  }

  const now = new Date().toISOString();
  const comment: Comment = {
    id: state.nextCommentId,
    author: input.author.trim(),
    body: input.body.trim(),
    createdAt: now,
  };

  const current = state.posts[index];
  const updated: Post = {
    ...current,
    updatedAt: now,
    comments: [...current.comments, comment],
  };

  const posts = state.posts.slice();
  posts[index] = updated;

  return {
    state: {
      posts,
      nextPostId: state.nextPostId,
      nextCommentId: state.nextCommentId + 1,
    },
    post: clonePost(updated),
  };
}

/**
 * Searches posts by query across title, excerpt, body, and tags.
 */
export function searchPosts(state: BlogState, query: string): SearchResult[] {
  const normalized = query.trim().toLowerCase();
  if (!normalized) {
    return [];
  }

  const results: SearchResult[] = [];
  for (const post of state.posts) {
    const score = computeScore(post, normalized);
    if (score > 0) {
      results.push({ post: clonePost(post), score });
    }
  }

  return results.sort((a: SearchResult, b: SearchResult) => b.score - a.score || a.post.id - b.post.id);
}

/**
 * Runs a small console-friendly demo flow and returns a formatted transcript.
 */
export function runDemo(): string {
  let state = createSeededBlogState();
  const lines: string[] = [];

  lines.push('=== Blog Demo ===');
  lines.push(`Seeded posts: ${state.posts.length}`);
  lines.push('');

  lines.push('List posts:');
  for (const post of listPosts(state)) {
    lines.push(`- [${post.id}] ${post.title} (${post.slug})`);
  }
  lines.push('');

  const read = readPost(state, 'hello-typescript');
  lines.push('Read by slug:');
  lines.push(read ? `${read.title}: ${read.excerpt}` : 'Post not found');
  lines.push('');

  const created = createPost(state, {
    title: 'Pure Operations',
    body: 'All actions return new state values instead of mutating the existing state.',
    tags: ['typescript', 'functional'],
  });
  state = created.state;
  lines.push('Created post:');
  lines.push(`- [${created.post.id}] ${created.post.title} (${created.post.slug})`);
  lines.push('');

  const commented = addComment(state, {
    slug: created.post.slug,
    author: 'Casey',
    body: 'Nice example of immutable updates.',
  });
  if (commented) {
    state = commented.state;
    lines.push('Added comment:');
    lines.push(`- ${commented.post.comments.length} comment(s) on ${commented.post.title}`);
  }
  lines.push('');

  lines.push('Search results for "demo":');
  for (const result of searchPosts(state, 'demo')) {
    lines.push(`- (${result.score}) ${result.post.title}`);
  }

  return lines.join('\n');
}

/**
 * Helper used by the demo to clone a post deeply enough for safe external usage.
 */
function clonePost(post: Post): Post {
  return {
    ...post,
    tags: [...post.tags],
    comments: post.comments.map((comment: Comment) => ({ ...comment })),
  };
}

function buildExcerpt(body: string): string {
  const trimmed = body.trim().replace(/\s+/g, ' ');
  return trimmed.length <= 120 ? trimmed : `${trimmed.slice(0, 117)}...`;
}

function normalizeTags(tags: string[] | undefined): string[] {
  if (!tags) {
    return [];
  }
  return tags.map((tag: string) => tag.trim()).filter((tag: string) => tag.length > 0);
}

function slugify(value: string): string {
  return value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function uniqueSlug(posts: Post[], baseSlug: string): string {
  let candidate = baseSlug || 'post';
  let suffix = 2;
  while (posts.some((post: Post) => post.slug === candidate)) {
    candidate = `${baseSlug}-${suffix}`;
    suffix += 1;
  }
  return candidate;
}

function findPostIndex(posts: Post[], postId: number | undefined, slug: string | undefined): number {
  if (typeof postId === 'number') {
    return posts.findIndex((post: Post) => post.id === postId);
  }
  if (typeof slug === 'string') {
    return posts.findIndex((post: Post) => post.slug === slug);
  }
  return -1;
}

function computeScore(post: Post, query: string): number {
  let score = 0;
  const fields = [post.title, post.excerpt, post.body, post.tags.join(' ')].map((value: string) => value.toLowerCase());

  for (const field of fields) {
    if (field.includes(query)) {
      score += 2;
    }
  }

  const words = query.split(/\s+/).filter((word: string) => word.length > 0);
  for (const word of words) {
    if (post.title.toLowerCase().includes(word)) score += 3;
    if (post.excerpt.toLowerCase().includes(word)) score += 2;
    if (post.body.toLowerCase().includes(word)) score += 1;
    if (post.tags.some((tag: string) => tag.toLowerCase().includes(word))) score += 2;
  }

  return score;
}

if (require.main === module) {
  process.stdout.write(runDemo() + '\n');
}

