/**
 * Tests for the blog demo behaviors.
 */

import {
  addComment,
  createPost,
  createSeededBlogState,
  listPosts,
  readPost,
  searchPosts,
} from './blog-demo';

import type { BlogState, Post } from './blog-demo';

function assert(condition: boolean, message: string): void {
  if (!condition) {
    throw new Error(message);
  }
}

function assertEqual<T>(actual: T, expected: T, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message} (expected ${String(expected)}, got ${String(actual)})`);
  }
}

function assertDeepEqual(actual: unknown, expected: unknown, message: string): void {
  const actualJson: string = JSON.stringify(actual);
  const expectedJson: string = JSON.stringify(expected);
  if (actualJson !== expectedJson) {
    throw new Error(`${message} (expected ${expectedJson}, got ${actualJson})`);
  }
}

function assertPostShape(post: Post): void {
  assert(typeof post.id === 'number', 'post.id should be a number');
  assert(typeof post.slug === 'string', 'post.slug should be a string');
  assert(typeof post.title === 'string', 'post.title should be a string');
  assert(typeof post.excerpt === 'string', 'post.excerpt should be a string');
  assert(typeof post.body === 'string', 'post.body should be a string');
  assert(Array.isArray(post.tags), 'post.tags should be an array');
  assert(typeof post.createdAt === 'string', 'post.createdAt should be a string');
  assert(typeof post.updatedAt === 'string', 'post.updatedAt should be a string');
  assert(Array.isArray(post.comments), 'post.comments should be an array');
}

function getSeededState(): BlogState {
  return createSeededBlogState();
}

function runTests(): void {
  // Seed data shape
  const seededState: BlogState = getSeededState();
  assertEqual(seededState.posts.length, 3, 'seeded state should contain three posts');
  assertEqual(seededState.nextPostId, 4, 'seeded state should set nextPostId to 4');
  assertEqual(seededState.nextCommentId, 3, 'seeded state should set nextCommentId to 3');
  for (const post of seededState.posts) {
    assertPostShape(post);
  }
  assertEqual(seededState.posts[0].comments.length, 1, 'first seeded post should have one comment');
  assertEqual(seededState.posts[1].comments.length, 0, 'second seeded post should have no comments');

  // Post listing
  const listedPosts: Post[] = listPosts(seededState);
  assertEqual(listedPosts.length, 3, 'listPosts should return all seeded posts');
  assertEqual(listedPosts[0].title, 'Hello TypeScript', 'listPosts should preserve post order');
  assert(listedPosts[0] !== seededState.posts[0], 'listPosts should return cloned posts');
  assert(listedPosts[0].comments[0] !== seededState.posts[0].comments[0], 'listPosts should clone nested comments');

  // Single-post lookup
  const lookupBySlug: Post | undefined = readPost(seededState, 'hello-typescript');
  assert(lookupBySlug !== undefined, 'readPost should find a post by slug');
  assertEqual(lookupBySlug?.id, 1, 'readPost should return the correct post by slug');
  const lookupById: Post | undefined = readPost(seededState, 3);
  assert(lookupById !== undefined, 'readPost should find a post by id');
  assertEqual(lookupById?.slug, 'searching-posts', 'readPost should return the correct post by id');
  assert(readPost(seededState, 'missing-post') === undefined, 'readPost should return undefined for missing posts');

  // Post creation
  const createdResult = createPost(seededState, {
    title: ' New Post Title ',
    body: 'This is the body for a newly created post.',
    tags: [' ts ', '', 'demo'],
  });
  assertEqual(createdResult.state.posts.length, 4, 'createPost should append a new post');
  assertEqual(createdResult.state.nextPostId, 5, 'createPost should increment nextPostId');
  assertEqual(createdResult.state.nextCommentId, 3, 'createPost should not change nextCommentId');
  assertEqual(createdResult.post.title, 'New Post Title', 'createPost should trim title');
  assertEqual(createdResult.post.slug, 'new-post-title', 'createPost should slugify the title');
  assertDeepEqual(createdResult.post.tags, ['ts', 'demo'], 'createPost should normalize tags');
  assert(createdResult.post.excerpt.length > 0, 'createPost should generate an excerpt when one is not provided');

  const duplicateSlugResult = createPost(createdResult.state, {
    title: 'Hello TypeScript',
    excerpt: 'Custom excerpt',
    body: 'Another body.',
  });
  assertEqual(duplicateSlugResult.post.slug, 'hello-typescript-2', 'createPost should ensure unique slugs');

  // Comment addition
  const commentedResult = addComment(seededState, {
    postId: 2,
    author: ' Grace ',
    body: ' Nice post! ',
  });
  assert(commentedResult !== undefined, 'addComment should return a result for existing post');
  assertEqual(commentedResult?.state.nextCommentId, 4, 'addComment should increment nextCommentId');
  assertEqual(commentedResult?.post.comments.length, 1, 'addComment should append a comment');
  assertEqual(commentedResult?.post.comments[0].author, 'Grace', 'addComment should trim author');
  assertEqual(commentedResult?.post.comments[0].body, 'Nice post!', 'addComment should trim body');
  assertEqual(seededState.posts[1].comments.length, 0, 'addComment should not mutate the original state');
  assert(addComment(seededState, { slug: 'does-not-exist', author: 'X', body: 'Y' }) === undefined, 'addComment should return undefined for missing post');

  // Search behavior
  const searchByTitle = searchPosts(seededState, 'typescript');
  assert(searchByTitle.length > 0, 'searchPosts should find matching posts');
  assertEqual(searchByTitle[0].post.slug, 'hello-typescript', 'searchPosts should rank title/tag matches highly');

  const searchByTag = searchPosts(seededState, 'crud');
  assertEqual(searchByTag[0].post.slug, 'in-memory-patterns', 'searchPosts should match tags');

  const searchByBody = searchPosts(seededState, 'simple demo');
  assert(searchByBody.some((result: { post: Post }) => result.post.slug === 'searching-posts'), 'searchPosts should match body text');

  const emptySearch = searchPosts(seededState, '   ');
  assertDeepEqual(emptySearch, [], 'searchPosts should return an empty array for blank queries');
}

runTests();
console.log('blog-demo tests passed');
